//Lots of code inspiration from iq, FrabiceNeyret, and many awesome people here.
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec3 col = texture(iChannel0,fragCoord.xy/iResolution.xy).rgb/float(iFrame);
    col = pow( clamp(col,0.0,1.0), vec3(1.0) );
    fragColor = vec4( col, 1.0 );
}

uint base_hash(uvec2 p) {
    p = 1103515245U*((p >> 1U)^(p.yx));
    uint h32 = 1103515245U*((p.x)^(p.y>>3U));
    return h32^(h32 >> 16);
}

float g_seed = 0.;

float hash1(inout float seed) {
    uint n = base_hash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    return float(n)/float(0xffffffffU);
}

vec2 hash2(inout float seed) {
    uint n = base_hash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    uvec2 rz = uvec2(n, n*48271U);
    return vec2(rz.xy & uvec2(0x7fffffffU))/float(0x7fffffff);
}

vec3 hash3(inout float seed) {
    uint n = base_hash(floatBitsToUint(vec2(seed+=.1,seed+=.1)));
    uvec3 rz = uvec3(n, n*16807U, n*48271U);
    return vec3(rz & uvec3(0x7fffffffU))/float(0x7fffffff);
}

mat2 rot(float a){
    return mat2(cos(a),sin(a),-sin(a),cos(a));
}

vec3 hsv2rgb( in vec3 c )
{
    vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
	return c.z * mix( vec3(1.0), rgb, c.y);
}

//Scene SDF, just a bunch of spheres and a plane
vec2 map(vec3 p)
{
    vec2 res = vec2(1000.0,-1.0);
    float f;  
    vec3 pp = p;

    pp -= vec3(0.0,0.0,0.0);
    pp.xz*=rot(0.8);
    pp.xy*=rot(0.7);

    f = length(pp)-0.75;
    if( f < res.x ) res = vec2(f,1.0);

    pp = p;
    pp -= vec3(1.0*cos(0.5),-0.4,-1.0*sin(0.5));
    f = length(pp)-0.4;
    if( f < res.x ) res = vec2(f,1.0);

    pp = p;
    float rad = 7.0;
    pp -= vec3(-0.71*rad+2.0,-0.0,0.71*rad+3.0);
    f = length(pp)-rad;
    if( f < res.x ) res = vec2(f,1.5);

    pp = p;
    rad = 7.0;
    pp -= vec3(0.71*rad+4.0,-0.0,-0.71*rad+3.0);
    f = length(pp)-rad;
    if( f < res.x ) res = vec2(f,1.5);

    pp = p;
    f = pp.y + 1.0;
    if(f < res.x) res = vec2(f,2.0);

    return res;
}

//Normal SDF computation
vec3 normal( vec3 pos )
{
    const vec2 eps = vec2(0.0001,0.0);
    return normalize( vec3(
      map( pos+eps.xyy ).x - map( pos-eps.xyy ).x,
      map( pos+eps.yxy ).x - map( pos-eps.yxy ).x,
      map( pos+eps.yyx ).x - map( pos-eps.yyx ).x ) );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //Seed for global noise
    g_seed = float(base_hash(floatBitsToUint(fragCoord)))/float(0xffffffffU)+10.0*iTime;

    vec2 uv = fragCoord.xy / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    //Bit of camera jittering to avoid some artifacts
    uv+=0.0025*(hash2(g_seed)-0.5);    
    vec3 ro = vec3( uv, 0.0 );
    vec3 rd = normalize( vec3( uv, 1.0 ) );

    //Camera setup
    ro.z-=2.0;
    ro.y-=0.25;

    ro.yz *= rot( -0.7 );
    rd.yz *= rot( -0.7 );
    ro.xz *= rot( 0.2 );
    rd.xz *= rot( 0.2 );


    //Directional light
    vec3 ldir = normalize(vec3(8.0,9.0,10.0));

    //Initialize final color for this pass
    vec3 col = vec3(0.0,0.0,0.0);

    //Each time we simulate a color. Useful for any refraction thing.
    float rand = hash1(g_seed);
    vec3 colmask = hsv2rgb(vec3(rand,1.0,4.0));

    //More path tracer variables
    float mask = 1.0;
    float bounces = 0.0;
    float maxscreenbounces = 10.0;

    //Asymmetric bounce count. More likely the contribution of direct lighting.
    float maxbounces = floor(maxscreenbounces*exp(-6.0*hash1(g_seed)));    
    float i = 0.0;
    for(; i<300.0; i+=1.0)
    {  
        vec2 res = map(ro);
        if(abs(res.x)<0.005)
        {

            vec3 nor = normal(ro);
            ro += 0.01*nor;
            if(res.y==1.0)
            {      

                float tile = smoothstep(-0.001,0.001,sin(20.0*ro.x)*sin(20.0*ro.z)*sin(20.0*ro.y));    
                vec3 rd1 = normalize(hash3(g_seed)-0.5);
                rd1 *= sign(dot(rd1,nor));
                rd = normalize(reflect(rd+0.05*normalize(hash3(g_seed)-0.5),nor));                
                rd = normalize(mix(rd,rd1,0.3*tile)); 
                colmask *= mix(vec3(0.5,1.0,0.0),vec3(0.7,1.0,0.3),tile);
            }

            if(res.y==2.0)
            {
                float tile = smoothstep(-0.001,0.001,sin(6.0*ro.x)*sin(6.0*ro.z));
                vec3 rd1 = normalize( hash3(g_seed)-0.5 );
                rd1 *= sign(dot(rd1,nor));
                rd = normalize(reflect(rd+0.02*normalize(hash3(g_seed)-0.5),nor));                
                rd = normalize(mix(rd,rd1,0.5*tile+0.05));      
                colmask *= (0.5+0.5*tile);
            }

            if(res.y==1.5)
            {      

                float tile = smoothstep(-0.001,0.001,sin(5.0*ro.x)*sin(5.0*ro.z)*sin(5.0*ro.y));
                vec3 rd1 = normalize( hash3(g_seed)-0.5 );
                rd1 *= sign(dot(rd1,nor));
                rd = normalize(reflect(rd+0.03*normalize(hash3(g_seed)-0.5),nor));                
                rd = normalize(mix(rd,rd1,0.3*tile));       
                colmask *= vec3(1.0,0.9,0.8);
            }

            if(bounces==maxbounces) rd = normalize(ldir+0.2*rand*(hash3(g_seed)-0.5));
            mask*=max(0.0,dot(rd,nor));

            if(bounces>=maxbounces+1.0)
            {
                mask*=0.0;
                break;
            }

            bounces += 1.0;
        }

        ro += abs(res.x) * rd;
    }

    col = mask * colmask;
    col += texture(iChannel0,fragCoord.xy / iResolution.xy).rgb;
    fragColor = vec4(col,0.0);
}
